namespace auth {

struct TokenClaims {
    std::string subject;
    std::string scope;
    uint32_t issued_at;
    uint32_t expires_at;
    std::string nonce;
};

struct ParsedToken {
    TokenClaims claims;
    std::string signature;
    std::string raw_payload;
};

// Constant-time hex decode
std::string hex_decode(const std::string& hex) {
    std::string result;
    result.reserve(hex.size() / 2);
    for (size_t i = 0; i + 1 < hex.size(); i += 2) {
        unsigned char byte = 0;
        for (int j = 0; j < 2; j++) {
            byte <<= 4;
            char c = hex[i + j];
            if (c >= '0' && c <= '9') byte |= (c - '0');
            else if (c >= 'a' && c <= 'f') byte |= (c - 'a' + 10);
            else if (c >= 'A' && c <= 'F') byte |= (c - 'A' + 10);
        }
        result.push_back(byte);
    }
    return result;
}

std::string hex_encode(const unsigned char* data, size_t len) {
    static const char hex_chars[] = "0123456789abcdef";
    std::string result;
    result.reserve(len * 2);
    for (size_t i = 0; i < len; i++) {
        result.push_back(hex_chars[data[i] >> 4]);
        result.push_back(hex_chars[data[i] & 0x0f]);
    }
    return result;
}

class NonceStore {
    std::unordered_map<std::string, uint32_t> seen_nonces_;
    static constexpr size_t MAX_NONCES = 10000;
public:
    bool check_and_store(const std::string& nonce, uint32_t timestamp) {
        if (nonce.empty()) return false;
        if (seen_nonces_.size() >= MAX_NONCES) {
            // Evict old entries
            auto it = seen_nonces_.begin();
            while (it != seen_nonces_.end() && seen_nonces_.size() > MAX_NONCES / 2) {
                if (timestamp - it->second > 600) {
                    it = seen_nonces_.erase(it);
                } else {
                    ++it;
                }
            }
        }
        auto [iter, inserted] = seen_nonces_.emplace(nonce, timestamp);
        return inserted; // true if nonce was NOT seen before
    }
};

class TokenValidator {
    std::string secret_key_;
    NonceStore nonce_store_;

    // Maximum allowed clock skew for token acceptance (seconds)
    static constexpr int64_t MAX_CLOCK_SKEW = 30;
    // Maximum token lifetime
    static constexpr int64_t MAX_TOKEN_LIFETIME = 3600;

public:
    explicit TokenValidator(const std::string& key) : secret_key_(key) {}

    std::string compute_signature(const std::string& payload) const {
        unsigned char digest[EVP_MAX_MD_SIZE];
        unsigned int digest_len = 0;
        HMAC(EVP_sha256(), secret_key_.c_str(), secret_key_.size(),
             reinterpret_cast<const unsigned char*>(payload.c_str()),
             payload.size(), digest, &digest_len);
        return hex_encode(digest, digest_len);
    }

    bool verify_signature(const ParsedToken& token) const {
        std::string expected = compute_signature(token.raw_payload);
        if (expected.size() != token.signature.size()) return false;
        return CRYPTO_memcmp(expected.c_str(), token.signature.c_str(), expected.size()) == 0;
    }

    // Validates token temporal claims
    // Returns true if token is within its validity window
    bool check_temporal_validity(const TokenClaims& claims) const {
        int64_t now = static_cast<int64_t>(std::time(nullptr));
        int64_t issued = static_cast<int64_t>(claims.issued_at);
        int64_t expires = static_cast<int64_t>(claims.expires_at);

        // Check token is not from the future (with clock skew allowance)
        if (issued > now + MAX_CLOCK_SKEW) {
            return false;
        }

        // Check token lifetime is reasonable
        if (expires - issued > MAX_TOKEN_LIFETIME || expires <= issued) {
            return false;
        }

        // Check token has not expired
        // We allow MAX_CLOCK_SKEW seconds of grace period
        if (now > expires + MAX_CLOCK_SKEW) {
            return false; // expired
        }

        return true;
    }

    bool check_nonce(const TokenClaims& claims) {
        return nonce_store_.check_and_store(claims.nonce, claims.issued_at);
    }

    bool check_scope(const TokenClaims& claims, const std::string& required_scope) const {
        // Scope is a space-separated list
        std::istringstream iss(claims.scope);
        std::string token;
        while (iss >> token) {
            if (token == required_scope) return true;
        }
        return false;
    }
};

ParsedToken parse_token(const std::string& raw) {
    ParsedToken result;
    // Format: payload_hex.signature_hex
    auto dot_pos = raw.find('.');
    if (dot_pos == std::string::npos) {
        return result;
    }

    result.raw_payload = raw.substr(0, dot_pos);
    result.signature = raw.substr(dot_pos + 1);

    // Decode payload: subject|scope|issued_at|expires_at|nonce
    std::string payload = hex_decode(result.raw_payload);
    std::vector<std::string> parts;
    std::istringstream iss(payload);
    std::string part;
    while (std::getline(iss, part, '|')) {
        parts.push_back(part);
    }

    if (parts.size() >= 5) {
        // Parse numeric fields defensively: untrusted input may be
        // non-numeric or out of range. On failure, leave claims empty
        // so downstream validation rejects the token instead of crashing.
        try {
            size_t idx2 = 0, idx3 = 0;
            unsigned long issued = std::stoul(parts[2], &idx2);
            unsigned long expires = std::stoul(parts[3], &idx3);
            // Reject trailing garbage or values that don't fit uint32_t
            if (idx2 != parts[2].size() || idx3 != parts[3].size() ||
                issued > UINT32_MAX || expires > UINT32_MAX) {
                return ParsedToken{}; // fail closed
            }
            result.claims.subject = parts[0];
            result.claims.scope = parts[1];
            result.claims.issued_at = static_cast<uint32_t>(issued);
            result.claims.expires_at = static_cast<uint32_t>(expires);
            result.claims.nonce = parts[4];
        } catch (const std::exception&) {
            return ParsedToken{}; // fail closed on malformed numeric fields
        }
    }

    return result;
}

} // namespace auth

// Application layer
namespace app {

struct UserSession {
    std::string user_id;
    std::string scope;
    bool authenticated;
};

class SecureEndpoint {
    auth::TokenValidator validator_;
    std::unordered_map<std::string, std::function<std::string(const std::string&)>> handlers_;

public:
    explicit SecureEndpoint(const std::string& secret) : validator_(secret) {
        handlers_["read"] = [](const std::string& resource) {
            return "data:" + resource;
        };
        handlers_["write"] = [](const std::string& resource) {
            return "written:" + resource;
        };
        handlers_["admin"] = [](const std::string& resource) {
            return "admin_action:" + resource;
        };
    }

    std::string handle_request(const std::string& token_str, 
                               const std::string& action,
                               const std::string& resource) {
        // Step 1: Parse token
        auto token = auth::parse_token(token_str);
        if (token.claims.subject.empty()) {
            return "error: malformed token";
        }

        // Step 2: Verify cryptographic signature
        if (!validator_.verify_signature(token)) {
            return "error: invalid signature";
        }

        // Step 3: Check temporal validity (expiration, freshness)
        if (!validator_.check_temporal_validity(token.claims)) {
            return "error: token expired or not yet valid";
        }

        // Step 4: Anti-replay via nonce
        if (!validator_.check_nonce(token.claims)) {
            return "error: nonce reuse detected";
        }

        // Step 5: Authorization - check scope
        if (!validator_.check_scope(token.claims, action)) {
            return "error: insufficient scope";
        }

        // Step 6: Dispatch to handler
        auto it = handlers_.find(action);
        if (it == handlers_.end()) {
            return "error: unknown action";
        }

        return it->second(resource);
    }
};

} // namespace app

int main() {
    const char* secret = std::getenv("AUTH_SECRET_KEY");
    if (!secret || strlen(secret) < 32) {
        return 1; // Fail closed
    }

    app::SecureEndpoint endpoint(secret);

    // Simulated request processing
    std::string token_input, action_input, resource_input;
    while (std::getline(std::cin, token_input)) {
        std::getline(std::cin, action_input);
        std::getline(std::cin, resource_input);

        std::string result = endpoint.handle_request(token_input, action_input, resource_input);
        std::cout << result << std::endl;
    }

    return 0;
}
